import {publicPage,banner,tabs,filters,photo,esc} from './ui.js';

export function mediaLibrary(){
 const images=[['bear','Белый медведь'],['iceberg','Айсберг'],['mountain','Арктические горы'],['islands','Скалистые острова'],['aurora','Северное сияние'],['ship','Ледокол'],['whale','Кит'],['ice','Лёд и ледники']];
 return publicPage('media',banner('Медиатека','Фотографии, иллюстрации и видео Арктики.<br>Открывай, изучай, вдохновляйся.')+`<div class="container">${tabs(['Фотографии','Видео'],0,'media')}${filters([['Все годы','2026','2025','2024','2023'],['Все экспедиции','Арктика','Баренцево море']])}<div class="media-grid">${images.map(([image,title],i)=>`<button type="button" class="media-item" data-item data-action="image" data-image="${image}" data-category="Фотографии" data-meta="${2025-i%3} ${i===6?'Баренцево море':'Арктика'} ${esc(title)}" aria-label="${esc(title)}">${photo(image,title)}</button>`).join('')}<button type="button" class="media-item" data-item data-action="video" data-category="Видео" data-meta="2026 Арктика Арктическое путешествие фотофильм" aria-label="Арктическое путешествие, видео 30 секунд"><img src="assets/media/arctic-poster.webp" alt="Арктическое путешествие"><span class="play" aria-hidden="true">▶</span><span class="media-caption">Арктическое путешествие · 0:30</span></button></div><p><small data-found></small></p><div class="card media-audio-card"><h3>Музыка Арктики</h3><p>Спокойная оригинальная инструментальная композиция. Можно включить её здесь или кнопкой ♫ в углу экрана.</p><audio data-standalone-music controls preload="none" src="assets/media/arctic-ambient.m4a" aria-label="Оригинальная музыка Арктики"></audio></div></div>`);
}
